sections.code:
/* El orden de las capas se declara una vez. */
@layer reset, base, components, overrides;

@layer base { button { font: inherit; } }
@layer components { .boton { padding: .7rem 1rem; } }
@layer overrides { .boton { border-radius: 999px; } }

exampleVariants.code:
/* Las reglas de una capa posterior pueden prevalecer sobre una anterior. */
@layer base { .card { color: #475569; } }
@layer components { .card { color: #1e293b; } }

/* Mantené las capas con responsabilidades claras. */

/* Los estilos sin capa y los estilos !important tienen reglas de prioridad propias. */
@layer reset { button { border: 0; } }
button { border: 1px solid currentColor; }

