sections.code:
/* rem depende del tamaño de fuente raíz; % depende del contexto. */
html { font-size: 100%; }
.contenedor { width: min(90%, 70rem); margin-inline: auto; }
.titulo { font-size: 2rem; }

exampleVariants.code:
/* em es relativo al tamaño de fuente del elemento o su padre. */
.boton { font-size: 1rem; padding: .65em 1em; }
.boton--grande { font-size: 1.25rem; }

/* Combiná unidades según su función. */
.tarjeta { width: 100%; max-width: 32rem; padding: 1.25rem; }
.icono { width: 1.25em; height: 1.25em; }

