sections.code:
/* calc() combina unidades compatibles. */
.contenido { width: calc(100% - 2rem); max-width: 72rem; margin-inline: auto; }

/* clamp() define mínimo, valor flexible y máximo. */
.titulo { font-size: clamp(1.8rem, 4vw, 3.5rem); }

exampleVariants.code:
/* min() limita el ancho sin una media query. */
.tarjeta { width: min(100%, 34rem); }

/* max() asegura un padding mínimo. */
.seccion { padding-inline: max(1rem, 4vw); }

/* Una combinación de funciones mantiene el diseño fluido. */
.grilla { grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr)); }

/* Ajustá los límites al contenido real. */

