/* Variables globales para mantener una paleta coherente. */
:root { --color-acento: #2457c5; --espacio: 1rem; }
.boton { background: var(--color-acento); padding: var(--espacio); }

exampleVariants.code:
/* Un componente puede definir su propio valor. */
.tarjeta { --superficie: #f1f5f9; background: var(--superficie); padding: 1rem; }
.tarjeta--oscura { --superficie: #1e293b; color: white; }

/* Funciones de color modernas para ajustar un color existente. */
:root { --marca: oklch(58% .18 255); }
.boton { background: var(--marca); border-color: color-mix(in oklab, var(--marca), black 20%); }

