sections.code:
/* El tamaño final considera contenido, padding y borde. */
.tarjeta { width: 20rem; padding: 1.25rem; border: 1px solid #cbd5e1; margin-block: 1rem; }

/* Usá box-sizing para que las dimensiones sean previsibles. */
* { box-sizing: border-box; }

exampleVariants.code:
/* margin separa componentes; padding separa el contenido del borde. */
.panel { margin-block: 1.5rem; padding: 1rem 1.25rem; border: 1px solid #cbd5e1; }
.panel h2 { margin-block-start: 0; }

/* Un ancho máximo evita líneas demasiado largas. */
.articulo { width: min(100% - 2rem, 68ch); margin-inline: auto; }
.articulo img { max-width: 100%; height: auto; }

